import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { getErrorMessage } from "../api/errorMessage";

const roleHome = {
  customer: "/restaurants",
  restaurant: "/restaurant/dashboard",
  agent: "/agent/dashboard",
};

export default function Register() {
  const { register } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({
    name: "",
    email: "",
    password: "",
    phone: "",
    role: "customer",
    restaurantName: "",
  });
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  const update = (key) => (e) => setForm({ ...form, [key]: e.target.value });

  const submit = async (e) => {
    e.preventDefault();
    setError("");
    setBusy(true);
    try {
      const user = await register(form);
      navigate(roleHome[user.role] || "/");
    } catch (err) {
      setError(getErrorMessage(err, "Registration failed"));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="page page-narrow">
      <div className="eyebrow">Join HealthyFood</div>
      <h1>Create your account</h1>
      <hr className="route-rule" style={{ margin: "20px 0 28px" }} />
      <form onSubmit={submit}>
        <div className="field">
          <label>I am a…</label>
          <select value={form.role} onChange={update("role")}>
            <option value="customer">Customer</option>
            <option value="restaurant">Restaurant owner</option>
            <option value="agent">Delivery agent</option>
          </select>
        </div>
        <div className="field">
          <label>Full name</label>
          <input value={form.name} onChange={update("name")} required />
        </div>
        {form.role === "restaurant" && (
          <div className="field">
            <label>Restaurant name</label>
            <input value={form.restaurantName} onChange={update("restaurantName")} placeholder="e.g. Green Bowl Kitchen" />
          </div>
        )}
        <div className="field">
          <label>Email</label>
          <input
            type="email"
            value={form.email}
            onChange={(e) => setForm({ ...form, email: e.target.value.trim().toLowerCase() })}
            autoComplete="email"
            required
          />
        </div>
        <div className="field">
          <label>Phone</label>
          <input value={form.phone} onChange={update("phone")} />
        </div>
        <div className="field">
          <label>Password</label>
          <input type="password" value={form.password} onChange={update("password")} minLength={6} required />
        </div>
        {error && <div className="error-text">{error}</div>}
        <button className="btn btn-primary btn-block" disabled={busy}>
          {busy ? "Creating account…" : "Create account"}
        </button>
      </form>
      <p style={{ marginTop: 18, fontSize: 14, color: "var(--paper-dim)" }}>
        Already have an account? <Link to="/login" style={{ color: "var(--signal)" }}>Log in</Link>
      </p>
    </div>
  );
}
